inputs.common/ai_strategies/00_default_strategy:
# This is a special strategy that sets the default values for different AI scores
# All AIs always load data from this strategy, which can then be either added to or overridden by data from its other strategies

ai_strategy_default = {
	icon = "gfx/interface/icons/ai_strategy_icons/placate_population.dds" # Never shown

	# If this trigger evaluates to true for any active strategy, the AI will try to form a power bloc
	# Empty trigger counts as evaluating false in this specific case
	will_form_power_bloc = {}

	# If this trigger evaluates to true for any active strategy, the AI will incorporate scope:target_state if it can afford it and if it's the highest value valid candidate
	# Empty trigger counts as evaluating false in this specific case
	# Capitals bypass this and start incorporating immediately if possible
	# Using this in a different strategy is inclusive, only one needs to return true
	# root = country, scope:target_state = the state being considered
	will_incorporate_state = {
		trigger_if = { # Colonies have a different behaviour
			limit = {
				country_is_colonial_or_company = yes
			}
			scope:target_state = { ai_colony_will_incorporate_state = yes }
		}
		trigger_else_if = { # Default behaviour
			limit = {
				scope:target_state = { ai_will_incorporate_state = yes }
			}
			always = yes
		}
		trigger_else = { # Content
			OR = {
				AND = {
					has_journal_entry = je_the_algerian_departements
					scope:target_state = {
						OR = {
							state_region = s:STATE_ORAN
							state_region = s:STATE_ALGIERS
							state_region = s:STATE_CONSTANTINE
						}
					}
				}
				AND = {
					has_journal_entry = je_french_natural_borders
					scope:target_state = {
						OR = {
							state_region = s:STATE_WALLONIA
							state_region = s:STATE_FLANDERS
							state_region = s:STATE_RHINELAND
							state_region = s:STATE_NORTH_RHINE
						}
					}
				}
				AND = {
					has_journal_entry = je_matter_of_hungary
					scope:target_state = {
						state_region = { is_homeland = cu:hungarian }
					}
				}
				AND = {
					has_journal_entry = je_la_trinitaria
					scope:target_state = {
						state_region = s:STATE_SANTO_DOMINGO
					}
				}
				AND = {
					has_journal_entry = je_colonize_korea
					scope:target_state = {
						is_in_geographic_region = geographic_region_korea
					}
				}
			}
		}
	}

	# These are the tax levels the AI will try to stay within, though it can go above max tax level if in a financial emergency
	# Using a different value in a strategy will override these values
	desired_tax_level = medium
	max_tax_level = high
	min_tax_level = low

	# The AI will avoid getting this much infamy unless it's a wargoal it really wants
	# Using a different value in a strategy will override this value
	undesirable_infamy_level = {
		value = 50
	}

	# The AI will never deliberately add wargoals that will bring its infamy this high
	# Using a different value in a strategy will override this value
	unacceptable_infamy_level = {
		value = 100
	}

	# How much is the AI's diplomatic acceptance, etc affected by government ideological differences
	# Using a different value in a strategy will function multiplicatively
	ideological_opinion_effect_mult = {
		value = 1.0
	}

	# Chance each day that the AI will stop enacting a law that is going to spark a civil war (1 aversion should translate into ~25% chance of avoiding a civil war)
	# Using a different value in a strategy will override this value
	revolution_aversion = {
		value = 5

		# Ottomans should avoid getting into revolutions before they deal with Egypt
		if = {
			limit = {
				has_journal_entry = je_sick_man_syria
				game_date < 1845.1.1
			}
			add = 100
		}

		if = {
			limit = {
				has_journal_entry = je_the_grand_collapse
			}
			add = 100
		}

		# Revolution aversion for July Monarchy
		if = {
			limit = { has_journal_entry = je_divided_monarchists }
			add = 100
		}
	}

	# If base chance for law to pass is below this, don't enact it
	# Using a different value in a strategy will override this value
	min_law_chance_to_pass = {
		value = 50
	}

	# The chance that the AI will negotiate with an IG when trying to enact a specific law, 1 = 100%
	# Using this value in other strategies will function additively
	# root = country
	# scope:law = law type being enacted
	# scope:interest_group = IG to negotiate with
	# scope:amenability = IG amenability to negotiation divided by MAX_AMENABILITY (ie, if MAX_AMENABILITY is 100 and IG amenability is 50, this value will be 0.5)
	# scope:advance_chance = Chance to advance law enactment
	# scope:stall_chance = Chance for law enactment to stall
	negotiation_chance = {
		value = 0

		if = {
			limit = {
				scope:interest_group ?= {
					amenability_level != 4
				}
			}
			value = scope:amenability

			add = scope:stall_chance

			if = {
				limit = {
					ai_has_reasons_to_not_oppose_law = yes
				}
				multiply = 2
			}

			subtract = {
				value = scope:advance_chance
				multiply = 2
			}
		}

		max = 1
	}

	# How progressive is the AI willing to be when passing laws
	# Using a different value in a strategy will override this value
	max_progressiveness = {
		value = 25
	}

	# How regressive is the AI willing to be when passing laws
	# Using a different value in a strategy will override this value
	max_regressiveness = {
		value = 25
	}

	# Added to willingness to support a country in diplomatic plays
	# Using this value in other strategies will function additively
	# root = supporting country doing the AI evaluation
	# scope:country = country we're evaluating support for (either initiator or target)
	# scope:enemy_country = the opposing side's leader
	# scope:diplomatic_play_type = the type of diplomatic play
	# scope:is_initiator = bool, set to true if evaluating support for initiator, false if target
	# NOTE: You need to include a description when adding values here so there are correct tooltips, this is different from most of ai strategy data!
	diplomatic_play_support = {
		value = 0

		add = {
			value = "scope:country.modifier:country_diplomatic_reputation_add"
			desc = "DIPLOMATIC_REPUTATION_REASON"
		}

		### German Leadership War
		if = {
			# Non-Germans should stay out of the leadership war unless they have a good reason to intervene
			limit = {
				scope:diplomatic_play_type = play_type:dp_leadership_germany
				NOR = {
					country_has_primary_culture = cu:north_german
					country_has_primary_culture = cu:south_german
				}
			}

			if = {
				limit = {
					NOR = {
						any_scope_treaty = {
							binds = scope:country
							any_scope_article = {
								has_type = alliance
							}
						}
						AND = {
							NOT = { exists = scope:is_initiator }
							OR = {
								any_scope_treaty = {
									binds = scope:country
									any_scope_article = {
										has_type = defensive_pact
									}
								}
								any_scope_treaty = {
									binds = scope:country
									any_scope_article = {
										has_type = guarantee_independence
									}
								}
							}
						}
					}

					scope:enemy_country = {
						NOR = {
							play_participant_has_war_goal_of_type_against = {
								type = conquer_state
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = make_protectorate
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = liberate_country
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = liberate_subject
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = transfer_subject
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = take_treaty_port
								target = scope:country
							}
						}
					}
				}

				add = {
					value = -200
					desc = "german_leadership_neutrality"
				}
			}
		}

		### Schleswig War
		if = {
			limit = {
				NOR = {
					country_has_primary_culture = cu:north_german
					country_has_primary_culture = cu:south_german
				}
				OR = {
					AND = {
						scope:country = {
							is_oppressor_of_schleswig_holstein = yes
						}
						scope:enemy_country = {
							has_journal_entry = je_schleswig_holstein_question
						}
					}
					AND = {
						scope:enemy_country = {
							is_oppressor_of_schleswig_holstein = yes
						}
						scope:country = {
							has_journal_entry = je_schleswig_holstein_question
						}
					}
				}
			}

			if = {
				limit = {
					NOR = {
						any_scope_treaty = {
							binds = scope:country
							any_scope_article = {
								has_type = alliance
							}
						}
						AND = {
							NOT = { exists = scope:is_initiator }
							OR = {
								any_scope_treaty = {
									binds = scope:country
									any_scope_article = {
										has_type = defensive_pact
									}
								}
								any_scope_treaty = {
									binds = scope:country
									any_scope_article = {
										has_type = guarantee_independence
									}
								}
							}
						}
					}

					scope:enemy_country = {
						NOR = {
							play_participant_has_war_goal_of_type_against = {
								type = conquer_state
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = make_protectorate
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = liberate_country
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = take_treaty_port
								target = scope:country
							}
							play_participant_has_war_goal_of_type_against = {
								type = enforce_treaty_article
								target = scope:country
							}
						}
					}
				}
				add = {
					value = -100
					desc = "je_schleswig_holstein_question"
				}
			}
		}

		### Ottomans vs Egypt - Great Powers pick sides
		if = {
			limit = {
				OR = {
					AND = {
						scope:country = { c:TUR ?= this }
						scope:enemy_country = { c:EGY ?= this }
					}
					AND = {
						scope:country = { c:EGY ?= this }
						scope:enemy_country = { c:TUR ?= this }
					}
				}
				c:TUR ?= {
					OR = {
						has_journal_entry = je_sick_man_syria
						has_journal_entry = je_sick_man_egypt
						has_journal_entry = je_veiled_protectorate
					}
				}
			}

			if = {
				limit = {
					has_variable = veiled_protectorate_support_ottomans
					OR = {
						AND = {
							NOT = { exists = scope:is_initiator }
							scope:enemy_country = { c:TUR ?= this }
						}
						AND = {
							exists = scope:is_initiator
							scope:country = { c:TUR ?= this }
						}
					}
				}

				add = {
					value = 100
					desc = "veiled_protectorate_ottomans_support"
				}
			}
			else_if = {
				limit = {
					has_variable = veiled_protectorate_support_egypt
					OR = {
						AND = {
							NOT = { exists = scope:is_initiator }
							scope:enemy_country = { c:EGY ?= this }
						}
						AND = {
							exists = scope:is_initiator
							scope:country = { c:EGY ?= this }
						}
					}
				}

				add = {
					value = 100
					desc = "veiled_protectorate_egypt_support"
				}
			}
		}

		### Risorgimento
		if = {
			limit = {
				exists = scope:is_initiator
				scope:diplomatic_play_type = play_type:dp_secession
				root = {
					has_variable = risorgimento_unifying_stance
				}
				scope:country = {
					OR = {
						country_has_primary_culture = cu:north_italian
						country_has_primary_culture = cu:south_italian
					}
				}
				scope:enemy_country = {
					NOR = {
						country_has_primary_culture = cu:north_italian
						country_has_primary_culture = cu:south_italian
					}
				}
			}
			add = {
				value = 150
				desc = "risorgimento_support"
			}
		}

		### The Great Game
		if = { # Great Powers will tend to meddle if you directly declare war on enemy countries to easily subjugate them.
			limit = {
				OR = {
					c:GBR ?= this
					c:RUS ?= this
				}
				OR = {
					has_journal_entry = je_great_game_control
					any_rival_country = {
						this = scope:enemy_country
					}
				}
				has_diplomatic_relevance = scope:enemy_country
				scope:enemy_country = { # enemy_country is the rival Great Power
					OR = {
						c:GBR ?= this
						c:RUS ?= this
					}
					NOT = {
						this = root
					}
					OR = {
						has_journal_entry = je_great_game_control
						any_rival_country = {
							this = root
						}
					}
				}
				scope:country = { # country is the country they're at war with
					OR = {
						capital.region = sr:region_greater_persia
						capital.region = sr:region_central_asia
					}
					NOT = {
						is_subject_of = scope:enemy_country
					}
				}
				can_reach_target_country = { TARGET_COUNTRY = scope:country }
			}
			if = {
				limit = {
					OR = { # They will meddle if you seek anything that subjugates them or harms the balance of power.
						scope:diplomatic_play_type = play_type:dp_make_protectorate
						scope:diplomatic_play_type = play_type:dp_join_power_bloc
						any_diplomatic_play = {
							scope:country = {
								is_diplomatic_play_enemy_of = scope:enemy_country
							}
							OR = {
								has_play_goal = make_protectorate
								has_play_goal = conquer_state
								has_play_goal = join_power_bloc
								has_play_goal = annex_country
							}
						}
					}
				}
				add = {
					value = 100
					desc = "defending_against_great_game_rival"
				}
			}
			else_if = {
				limit = {
					OR = { # They will meddle less if you just want to take states.
						scope:diplomatic_play_type = play_type:dp_conquer_state
						any_diplomatic_play = {
							scope:country = {
								is_diplomatic_play_enemy_of = scope:enemy_country
							}
							OR = {
								has_play_goal = conquer_state
							}
						}
					}
				}
				add = {
					value = 50
					desc = "defending_against_great_game_rival"
				}
			}
			else = {
				add = {
					value = 25
					desc = "defending_against_great_game_rival"
				}
			}
		}

		if = { # Britain will step in in favour of an Afghan country that it's supporting
			limit = {
				OR = {
					c:GBR ?= this
				}
				has_variable = committed_to_afghanistan_assistance
				scope:country = {
					has_variable = AFG_appealed_to_GBR
				}
				scope:enemy_country = {
					OR = {
						country_has_primary_culture = cu:pashtun
						country_has_primary_culture = cu:tajik
					}
				}
			}
			add = {
				value = 50
				desc = "support_for_afghan_claimant"
			}
		}

		if = { # Subjects of an overlord that has committed to assisting a claimant will be more inclined to help.
			limit = {
				overlord ?= {
					has_variable = committed_to_afghanistan_assistance
				}
				OR = {
					AND = {
						exists = c:GBR
						is_subject_of = c:GBR
						scope:country = {
							has_variable = AFG_appealed_to_GBR
						}
					}
					AND = {
						exists = c:RUS
						is_subject_of = c:RUS
						scope:country = {
							has_variable = AFG_appealed_to_RUS
						}
					}
				}
				scope:enemy_country = {
					OR = {
						country_has_primary_culture = cu:pashtun
						country_has_primary_culture = cu:tajik
					}
				}
			}
			add = {
				value = 50
				desc = "overlord_support_for_afghan_claimant"
			}
		}

		if = { # Britain will step in in favour of an Afghan country that it's supporting
			limit = {
				c:RUS ?= this
				has_variable = committed_to_afghanistan_assistance
				scope:country = {
					has_variable = AFG_appealed_to_RUS
				}
				scope:enemy_country = {
					OR = {
						country_has_primary_culture = cu:pashtun
						country_has_primary_culture = cu:tajik
					}
				}
			}
			add = {
				value = 50
				desc = "support_for_afghan_claimant"
			}
		}

		if = { # Donghak Rebellion - Japanese Behaviours - Pro-Government
			limit = {
				c:JAP ?= this
				is_involved_in_journal_entry = je_korean_rebellion
				has_variable = sided_with_korean_gov
				scope:country = {
					country_has_primary_culture = cu:korean
					is_revolutionary = no
				}
			}
			add = {
				value = 100
				desc = "committed_to_upholding_korean_government"
			}
		}

		if = { # Donghak Rebellion - Japanese Behaviours - Anti-Government
			limit = {
				c:JAP ?= this
				is_involved_in_journal_entry = je_korean_rebellion
				has_variable = sided_with_korean_rebels
				scope:country = {
					country_has_primary_culture = cu:korean
					is_revolutionary = yes
				}
			}
			add = {
				value = 100
				desc = "committed_to_overthrowing_korean_government"
			}
		}

		if = { # Modernised Japan and Russia will defend Korea from one another
			limit = {
				c:RUS ?= this
				scope:country = {
					country_has_primary_culture = cu:korean
				}
				scope:enemy_country = {
					country_has_primary_culture = cu:japanese
				}
			}
			add = {
				value = 50
				desc = "defending_korea"
			}
		}

		if = { # Modernised Japan and Russia will defend Korea from one another
			limit = {
				c:JAP ?= this
				NOT = {
					has_law_or_variant = law_type:law_isolationism
					has_law_or_variant = law_type:law_closed_borders
				}
				scope:country = {
					country_has_primary_culture = cu:korean
				}
				scope:enemy_country = {
					country_has_primary_culture = cu:russian
				}
			}
			add = {
				value = 50
				desc = "defending_korea"
			}
		}

		if = { # Qing and other Central Asian Khanates will be more willing help a player Kenesary Khan
			limit = {
				scope:country = {
					c:KAZ ?= this
					is_player = yes
				}
				has_strategic_adjacency = scope:country
				OR = {
					c:CHI ?= this
					capital.region = sr:region_central_asia
				}
				scope:enemy_country = {
					country_has_primary_culture = cu:russian
				}
			}
			add = {
				value = 50
				desc = "supporting_kenesary"
			}
		}

		if = { # Recognition of Kenesary
			limit = {
				scope:country = {
					c:KAZ ?= this
				}
				has_strategic_adjacency = scope:country
				has_variable = kenesary_recognizer_var
				scope:enemy_country = {
					country_has_primary_culture = cu:russian
				}
			}
			add = {
				value = 100
				desc = "recognised_kenesary"
			}
		}

		### Chinese unification warlord coalitions
		if = {
			limit = {
				has_journal_entry = je_reunify_china
				scope:country = {
					has_journal_entry = je_reunify_china
				}
				scope:enemy_country = {
					has_journal_entry = je_reunify_china
					this.country_rank >= scope:country.country_rank
			 	}
			}
			add = {
				value = 25
				desc = "alignment_politics"
			}
		}

		### Russia shouldn't join secession plays, since then it couldn't add wargoals of its own
		if = {
			limit = {
				exists = scope:is_initiator
				scope:diplomatic_play_type = play_type:dp_secession
				root = {
					c:RUS ?= this
					has_journal_entry = je_eastern_question_russia
				}
				OR = {
					scope:country = {
						country_has_primary_culture = cu:bulgarian
					}
					scope:enemy_country = {
						country_has_primary_culture = cu:bulgarian
					}
				}
				OR = {
					scope:enemy_country = {
						has_journal_entry = je_great_eastern_crisis
					}
					scope:country = {
						has_journal_entry = je_great_eastern_crisis
					}
				}
			}
			add = {
				value = -200
				desc = "focus_on_bulgaria"
			}
		}

 		### Austria doesn't want anything except for Bosnia
		if = {
			limit = {
				exists = scope:is_initiator
				scope:diplomatic_play_type = play_type:dp_secession
				root = {
					c:AUS ?= this
					has_journal_entry = je_eastern_question_austria
				}
				OR = {
					scope:enemy_country = {
						has_journal_entry = je_great_eastern_crisis
					}
					scope:country = {
						has_journal_entry = je_great_eastern_crisis
					}
				}
			}
			add = {
				value = -200
				desc = "focus_on_bosnia"
			}
		}

		### The Balkan League countries supporting each other against the Ottomans
		if = {
			limit = {
				has_journal_entry = je_the_balkan_league
				scope:country = {
					has_journal_entry = je_the_balkan_league
				}
				scope:enemy_country = {
					c:TUR ?= this
				}
			}
			add = {
				value = 1000
				desc = "support_for_balkan_league"
			}
		}

 		### War of the Confederation
		if = {
			limit = {
				exists = scope:is_initiator
				root = {
					has_variable = attack_bolivia
				}
				scope:country = {
