	# How much does the AI desire a state owned by another country
	# Using this value in other strategies will function additively
	# root = country
	# scope:target_state = state
	# scope:target_country = state owner
	treaty_port_value = {
		value = 0

		if = {
			limit = {
				# Because the target state in a treaty article is not actually the treaty port state, we need to check the entire state region
				scope:target_state = {
					state_region = {
						any_scope_state = {
							is_treaty_port = yes
							OR = {
								owner = { is_subject_of = ROOT }
								owner = ROOT
							}
						}
					}
				}
			}
			add = 40
		}

		if = {
			limit = {
				NOT = { is_country_type = unrecognized }
				scope:target_country = { is_country_type = unrecognized }
				NOT = { is_adjacent_to_country = scope:target_country } # No interest in treaty ports right next to our lands
				OR = {
					scope:target_country = {
						has_diplomatic_pact = {
							who = root
							type = embargo
						}
					}
					AND = {
						has_strategy = ai_strategy_economic_imperialism
						"mutual_trade_value_with_country(root)" >= 1000
						OR = {
							has_attitude = {
								who = scope:target_country
								attitude = belligerent
							}
							has_attitude = {
								who = scope:target_country
								attitude = domineering
							}
							has_attitude = {
								who = scope:target_country
								attitude = antagonistic
							}
						}
					}
				}
			}

			add = {
				value = 5

				add = {
					value = scope:target_state.state_population
					divide = 200000
					max = 10
				}

				add = {
					value = scope:target_state.gdp
					divide = 200000
					max = 10
				}

				if = {
					limit = {
						any_scope_building = {
							is_building_type = building_trade_center
							level > 0
						}
					}
					add = 5
				}

				if = {
					limit = {
						has_strategic_adjacency = scope:target_state
					}
					multiply = 1.50
				}

				if = {
					limit = {
						scope:target_state = { is_incorporated = no	}
					}
					multiply = 0.25
				}
			}
		}

		if = {
			limit = {
				has_journal_entry = je_opium_wars
				scope:target_country = {
					has_variable = opium_wars_target
				}
				scope:target_state = {
					NOT = { state_region = s:STATE_FORMOSA }
				}
			}
			add = 100
		}

		if = { #Carving up China
			limit = {
				should_carve_up_china = yes
				scope:target_state = {
					owner = { is_country_type = unrecognized }
					OR = {
						region = sr:region_north_china
						region = sr:region_south_china
						is_in_geographic_region = geographic_region_manchuria_old
					}
				}
			}
			add = 100
		}

		if = {
			limit = {
				# Because the target state in a treaty article is not actually the treaty port state, we need to check the entire state region
				scope:target_state = {
					NOT = {
						state_region = {
							any_scope_state = {
								is_treaty_port = yes
								OR = {
									owner = { is_subject_of = ROOT }
									owner = ROOT
								}
							}
						}
					}
				}
			}

			if = {
				limit = { has_treaty_port_in_market = scope:target_country.market }
				multiply = 0.25
			}

			# Don't want treaty ports on countries in our market
			if = {
				limit = {
					market_capital.market ?= scope:target_country.market_capital.market
				}
				multiply = 0.0
			}

			# Not worth doing against very small markets
			if = {
				limit = {
					scope:target_country = {
						gdp < 2000000
					}
				}
				multiply = 0
			}

			if = {
				limit = {
					scope:target_country = {
						any_scope_treaty = {
							binds = root
							any_scope_article = {
								has_type = trade_privilege
								source_country = scope:target_country
							}
						}
					}
				}
				multiply = 0.25
			}

			if = {
				limit = {
					NOT = { can_reach_target_state = { TARGET_STATE = scope:target_state } }
				}
				multiply = 0
			}
		}

		min = 0
		max = 100
	}

	# How much does the AI desire another country as their subject
	# Using this value in other strategies will function additively
	# root is the AI doing the evaluation, scope:target_country is prospective subject
	subject_value = {
		value = 0

		# PUT ALL REGULAR SUBJECT SCORES INSIDE THE BELOW IF STATEMENT TO PREVENT AI FROM TAKING UNREACHABLE SUBJECTS
		if = {
			limit = {
				OR = {
					scope:target_country = { is_subject_of = root }
					can_reach_target_country = { TARGET_COUNTRY = scope:target_country }
				}
			}

			if = {
				limit = {
					ai_is_regional_objective_subjugate_target = { TARGET = scope:target_country }
				}
				add = ai_regional_objective_subject_value
			}

			add = {
				if = {
					limit = {
						OR = {
							scope:target_country = { is_subject_of = root }
							has_attitude = {
								who = scope:target_country
								attitude = protective
							}
							has_attitude = {
								who = scope:target_country
								attitude = domineering
							}
						}
					}

					value = 50

					add = {
						value = scope:target_country.gdp
						divide = 200000
						max = 50
					}
				}

				if = {
					limit = {
						scope:target_country = { is_subject_of = root }
					}

					# AI values subjects it already has higher than subjects it might have, and will basically never give away large subjects with a lot of prestige
					if = {
						limit = {
							scope:target_country = {
								prestige >= 100
							}
						}
						multiply = 5.0
					}
					else_if = {
						limit = {
							scope:target_country = {
								prestige >= 75
							}
						}
						multiply = 4.0
					}
					else_if = {
						limit = {
							scope:target_country = {
								prestige >= 50
							}
						}
						multiply = 3.0
					}
					else_if = {
						limit = {
							scope:target_country = {
								prestige >= 25
							}
						}
						multiply = 2.0
					}
					else = {
						multiply = 1.5
					}
				}
				else = {
					if = {
						limit = {
							has_secret_goal = {
								who = scope:target_country
								secret_goal = protect
							}
						}

						multiply = 0.5
					}

					if = {
						limit = {
							NOT = {	has_strategic_adjacency = scope:target_country }
						}
						multiply = 0.5
					}
				}
			}

			if = {
				limit = {
					has_journal_entry = je_scramble_for_africa

					# Scramble for Africa powers should only care about the Boers once diamonds are found
					scope:target_country = {
						is_in_geographic_region = geographic_region_africa
						any_scope_building = {
							OR = {
								is_building_type = building_gold_mine
								is_building_type = building_gold_field
							}
						}
					}
				}
				add = 50
			}

			if = {
				limit = {
					OR = {
						has_journal_entry = je_sick_man_egypt
						has_journal_entry = je_veiled_protectorate
					}
					exists = c:EGY
					scope:target_country = c:EGY
				}
				add = 100
			}

			# Russian expansion into Central Asia
			if = {
				limit = {
					country_has_primary_culture = cu:russian
					has_law = law_type:law_national_supremacy # TODO - Official Nationality
					has_technology_researched = nationalism
					OR = {
						AND = {
							exists = c:KZH
							scope:target_country = {
								c:KZH ?= THIS
							}
						}
						AND = {
							exists = c:UZH
							scope:target_country = {
								c:UZH ?= THIS
							}
						}
						AND = {
							exists = c:OZH
							scope:target_country = {
								c:OZH ?= THIS
							}
						}
						AND = {
							exists = c:KOK
							scope:target_country = {
								c:KOK ?= THIS
							}
						}
						AND = {
							exists = c:KHI
							scope:target_country = {
								c:KHI ?= THIS
							}
						}
						AND = {
							exists = c:BUK
							scope:target_country = {
								c:BUK ?= THIS
							}
						}
					}
				}
				add = 100
			}

			if = { #Indian suzerain will be aggressive against Afganistan, if Afghanistan is threatened by Russia.
				limit = {
					AND = {
						c:RUS ?= {
							OR = {
								has_state_in_state_region = STATE_UZBEKIA
								has_state_in_state_region = STATE_KIRGHIZIA
								has_state_in_state_region = STATE_KHIVA
								has_state_in_state_region = STATE_TURKMENIA
								has_state_in_state_region = STATE_TAJIKISTAN
							}
						}
						ROOT = {
							is_in_geographic_region = geographic_region_europe
							OR = {
								any_scope_state = {
									is_in_geographic_region = geographic_region_india
									count >= 3
								}
								any_subject_or_below = {
									any_scope_state = {
										is_in_geographic_region = geographic_region_india
										count >= 3
									}
								}
							}
						}
						scope:target_country = {
							OR = {
								has_state_in_state_region = STATE_KABUL
								has_state_in_state_region = STATE_HERAT
								has_state_in_state_region = STATE_KANDAHAR
							}
						}
					}
				}
				add = 50
			}

			if = {
				limit = {
					lenient_ai_behavior_trigger = yes
				}
				multiply = 0.5
			}

			if = {
				limit = {
					AND = {
						has_radical_leftist_government = no
						scope:target_country = {
							has_radical_leftist_government = yes
						}
					}

				}
				multiply = 1.5
			}

			if = {
				limit = {
					AND = {
						has_radical_leftist_economy = no
						scope:target_country = {
							has_radical_leftist_economy = yes
						}
					}

				}
				multiply = 1.5
			}
		}

		if = {
			limit = {
				has_secret_goal = {
					who = scope:target_country
					secret_goal = dominate
				}
			}

			min = 25
		}

		# AI should open up large isolationist powers, not subjugate them
		if = {
			limit = {
				has_strategy = ai_strategy_economic_imperialism
				scope:target_country = {
					has_law_or_variant = law_type:law_isolationism
					gdp >= 5000000
				}
			}
			multiply = 0.0
		}

		if = {
			limit = {
				scope:target_country = { is_subject_of = root }
			}
			min = 100
			max = 1000
		}
		else = {
			min = 0
			max = 200
		}
	}

	# How much does the AI desire becoming another country's subject
	# Using this value in other strategies will function additively
	# root is the AI doing the evaluation, scope:overlord is prospective overlord
	become_subject_value = {
		value = -100

		if = {
			limit = {
				NOT = { has_strategic_adjacency = scope:overlord }
			}

			add = -10
		}

		if = {
			limit = {
				has_strategy = ai_strategy_armed_isolationism
			}

			add = -25
		}

		if = {
			limit = {
				"scope:overlord.ai_army_comparison(root)" > 0
			}
			add = {
				value = "scope:overlord.ai_army_comparison(root)"
				max = 25
			}
		}
		else = {
			add = -1000
		}

		if = {
			limit = {
				"scope:overlord.ai_ideological_opinion(root)" > 0
			}
			add = {
				value = "scope:overlord.ai_ideological_opinion(root)"
