		else_if = {
			limit = {
				"scope:overlord.ai_ideological_opinion(root)" < 0
			}
			add = {
				value = "scope:overlord.ai_ideological_opinion(root)"
				min = -30
			}
		}

		if = {
			limit = {
				is_in_customs_union_with = scope:overlord
			}
			add = 10
		}

		add = {
			if = {
				limit = {
					OR = {
						has_attitude = {
							who = scope:overlord
							attitude = genial
						}
						has_attitude = {
							who = scope:overlord
							attitude = conciliatory
						}
						has_attitude = {
