					"relations(scope:overlord)" < relations_threshold:cordial
				}
				value = -25
			}
			if = {
				limit = {
					"relations(scope:overlord)" >= relations_threshold:cordial
					"relations(scope:overlord)" < relations_threshold:amicable
				}
				value = 5
			}
			if = {
				limit = {
					"relations(scope:overlord)" >= relations_threshold:amicable
					"relations(scope:overlord)" < relations_threshold:friendly
				}
				value = 10
			}
			if = {
				limit = {
					"relations(scope:overlord)" >= relations_threshold:friendly
