	# How much construction output should the AI aim for
	# Using this value in other strategies will function additively
	wanted_construction_output = {
		# Accounts for the 2-10 free construction from base modifiers
		if = {
			limit = {
				OR = {
					has_game_rule = free_construction_unscaled
					AND = { # for when AI is enabled for player country via console
						is_ai = no
						has_game_rule = free_construction_scaled_player_exemption
					}
				}
			}
			add = 10
		}
		else = {
			add = {
				value = 2
				add = {
					value = gdp
					divide = 2000000
					multiply = 8
				}
				max = 10
			}
		}

		add = {
			value = investment_pool_income
			subtract = 7500 # So small nations don't overshoot early on
			divide = 750 # 1 construction output per this much into the investment pool
			min = 0
		}

		add = {
			value = fixed_income

			divide = 5000 # 1 construction output per this much income

			min = 0
			max = 200 # Above a certain point more government income isn't going to lead to more AI government construction
		}

		add = {
			value = total_population

			divide = 2000000 # 1 construction output per this much population
			max = 100
		}

		# Kickstart private investors If above this population value
		if = {
			limit = {
				total_population >= 2000000
			}
			add = 10
		}

		# Add a baseline for high rank
		if = {
			limit = { country_rank >= rank_value:great_power }
			add = 75
		}
		else_if = {
			limit = {
				country_rank >= rank_value:major_power
			}
			add = 50
		}
		else_if = {
			limit = {
				country_rank >= rank_value:unrecognized_major_power
			}
			add = 25
		}

		# If trying to industrialize
		if = {
			limit = {
				OR = {
					has_strategy = ai_strategy_resource_expansion
					has_strategy = ai_strategy_industrial_expansion
				}
			}
			multiply = 1.25
		}

		# If has Grunderzeit
		if = {
			limit = {
				has_journal_entry = je_grunderzeit
			}
			multiply = 1.5
		}

		if = {
			limit = {
				OR = {
					has_journal_entry = je_meiji_restoration
					has_journal_entry = je_meiji_main
				}
			}
			multiply = 2.0
		}

		if = {
			limit = { has_law_or_variant = law_type:law_traditionalism }
			multiply = 0.5
		}

		if = {
			limit = { has_strategy = ai_strategy_maintain_mandate_of_heaven }
			multiply = 0.1
		}

		# Multiply final value by diplomatic pact expenses ratio - countries paying a lot to pacts have lower spending ambitions
		multiply = {
			value = 1
			subtract = diplomatic_pact_expense_ratio
		}

		if = { # Ensure that countries where construction sectors would be extremely volatile do not construct them
			limit = {
				total_population <= 250000
			}
			multiply = 0
		}

		min = 0
	}

