	# How important is it that the AI maintains an interest in a specific strategic region (added on top of region value calculations set in defines)
	# Using this value in other strategies will function additively
	strategic_region_scores = {
		value = 0

		# Base Value
		add = {
			value = 100

			add = {
				scope:region = {
					add = gdp
				}
				divide = 40000
				max = 50
			}

			every_rival_country = {
				limit = {
					has_strategic_region_interest_tier = {
						strategic_region = scope:region
						value >= 1
					}
				}
				add = 25
			}

			scope:region = {
				every_scope_state = {
					limit = {
						is_homeland_of_country_cultures = root
					}
					add = 10
				}
			}
		}

		# We care about the things happening at home
		if = {
			limit = {
				any_scope_state = {
					region = scope:region
				}
			}
			add = 50

			if = {
				limit = {
					scope:region = {
						any_scope_state = {
							owner = root
							is_incorporated = yes
						}
					}
				}
				add = 50
			}

			if = {
				limit = {
					scope:region = capital.region
				}
				add = 100
			}
		}

		# Certain Great Powers care about Egyptian-Ottoman conflict in the early game
		if = {
			limit = {
				exists = c:TUR
				exists = c:EGY
				OR = {
					has_variable = veiled_protectorate_support_ottomans
					has_variable = veiled_protectorate_support_egypt
				}
				OR = {
					navy_size >= 25
					is_adjacent_to_country = c:TUR
					is_adjacent_to_country = c:EGY
				}
				scope:region = {
					OR = {
						this = sr:region_near_east
						this = sr:region_arabia
						this = sr:region_nile_basin
						this = sr:region_balkans
					}
				}
			}
			add = 500
		}

		# Britain is participating in the Caucasian War in a certain capacity early game.
		if = {
			limit = {
				c:GBR ?= this
				exists = c:CIR
				country_rank = rank_value:great_power
				navy_size >= 50
				scope:region = sr:region_russia
			}
			add = 100
		}

		# Annexation of Hawaii
		if = {
			limit = {
				OR = {
					has_variable = hawaii_interest
					c:USA ?= this
					AND = {
						has_global_variable = gp_hawaii_interest
						country_rank = rank_value:great_power
						OR = {
							is_in_geographic_region = geographic_region_north_america
							is_in_geographic_region = geographic_region_south_america
						}
					}
				}
				scope:region = sr:region_oceania
			}
			add = 200
		}

		# Sakoku
		if = {
			limit = {
				exists = c:JAP
				c:JAP = { has_law_or_variant = law_type:law_isolationism }
				NOT = { country_rank = rank_value:great_power }
				scope:region = sr:region_northeast_asia
			}
			add = -50
		}

		# Scramble for Africa
		if = {
			limit = {
				OR = {
					AND = {
						country_rank = rank_value:great_power
						has_technology_researched = malaria_prevention
					}
					has_journal_entry = je_scramble_for_africa
				}
				scope:region = {
					OR = {
						this = sr:region_nile_basin
						this = sr:region_north_africa
						this = sr:region_west_africa
						this = sr:region_equatorial_africa
						this = sr:region_southern_africa
						this = sr:region_east_africa
					}
				}
			}
			add = 200
		}

		# Great Powers always care about Europe somehwat
		if = {
			limit = {
				is_in_geographic_region = geographic_region_europe
				country_rank >= rank_value:great_power
				scope:region = {
					is_in_geographic_region = geographic_region_europe
				}
			}
			add = 50

			if = {
				limit = {
					scope:region = {
						OR = {
							is_in_geographic_region = geographic_region_north_germany_old
							is_in_geographic_region = geographic_region_south_germany_old
							is_in_geographic_region = geographic_region_rhine_old
						}
					}
				}
				add = 50

				if = {
					limit = {
						has_journal_entry = je_german_unification
					}
					add = 1000
				}
			}
			else_if = {
				limit = {
					scope:region = {
						is_in_geographic_region = geographic_region_italy_old
					}
				}
				add = 50
			}
		}

		# Europeans generally dont have any business in the Americas
		if = {
			limit = {
				is_in_geographic_region = geographic_region_europe
				NOT = {
					any_scope_state = {
						is_in_geographic_region = geographic_region_americas
					}
				}
				scope:region = {
					is_in_geographic_region = geographic_region_americas
				}
			}

			# Unless they do!
			if = {
				limit = {
					has_journal_entry = je_aberdeen_act
				}
